import{_ as a,c as n,o as r,aj as t}from"./chunks/framework.CIIM_L32.js";const u=JSON.parse(`{"title":"Core Components Overview","description":"Overview of Torch-RecHub's core components","frontmatter":{"title":"Core Components Overview","description":"Overview of Torch-RecHub's core components"},"headers":[],"relativePath":"core/intro.md","filePath":"en/core/intro.md"}`),o={name:"core/intro.md"};function i(s,e,l,d,c,g){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="core-components-overview" tabindex="-1">Core Components Overview <a class="header-anchor" href="#core-components-overview" aria-label="Permalink to “Core Components Overview”">​</a></h1><p>Torch-RecHub uses a modular design that divides the core functionality of a recommender system into components for feature processing, data pipelines, model design, training, and evaluation. This modular design makes the framework easy to use and extend while preserving a well-organized codebase.</p><h2 id="core-component-architecture" tabindex="-1">Core Component Architecture <a class="header-anchor" href="#core-component-architecture" aria-label="Permalink to “Core Component Architecture”">​</a></h2><p>Torch-RecHub&#39;s core component architecture is organized as follows:</p><ol><li><strong>Feature layer</strong>: Handles different types of features, including numerical, categorical, and sequence features</li><li><strong>Data layer</strong>: Handles data loading, preprocessing, and DataLoader generation</li><li><strong>Model layer</strong>: Implements recommendation models, including ranking, matching, multi-task, and generative recommendation models</li><li><strong>Training layer</strong>: Provides unified training interfaces for model training, evaluation, prediction, and ONNX export</li><li><strong>Tools layer</strong>: Provides utilities such as ONNX export, model visualization, callbacks, and loss functions</li></ol><h2 id="component-relationships" tabindex="-1">Component Relationships <a class="header-anchor" href="#component-relationships" aria-label="Permalink to “Component Relationships”">​</a></h2><p>The core components relate to one another as follows:</p><ol><li><strong>Feature layer</strong> -&gt; <strong>Data layer</strong>: Feature definitions guide preprocessing and feature engineering in the data layer</li><li><strong>Data layer</strong> -&gt; <strong>Training layer</strong>: DataLoaders produced by data generators are used for model training and evaluation</li><li><strong>Model layer</strong> -&gt; <strong>Training layer</strong>: The training layer trains and evaluates models defined in the model layer</li><li><strong>Training layer</strong> -&gt; <strong>Tools layer</strong>: The training layer uses utilities for tasks such as ONNX export and model visualization</li></ol><h2 id="component-details" tabindex="-1">Component Details <a class="header-anchor" href="#component-details" aria-label="Permalink to “Component Details”">​</a></h2><h3 id="feature-processing" tabindex="-1">Feature Processing <a class="header-anchor" href="#feature-processing" aria-label="Permalink to “Feature Processing”">​</a></h3><p>The feature-processing component defines and handles different types of features, including:</p><ul><li><strong>DenseFeature</strong>: Handles numerical features</li><li><strong>SparseFeature</strong>: Handles categorical features</li><li><strong>SequenceFeature</strong>: Handles sequence or multi-hot features</li></ul><p>See <a href="/torch-rechub/core/features.html">Feature Definitions</a> for details.</p><h3 id="data-pipeline" tabindex="-1">Data Pipeline <a class="header-anchor" href="#data-pipeline" aria-label="Permalink to “Data Pipeline”">​</a></h3><p>The data-pipeline component handles data loading, preprocessing, and DataLoader generation, including:</p><ul><li><strong>TorchDataset</strong>: A dataset for training and validation</li><li><strong>PredictDataset</strong>: A dataset for prediction</li><li><strong>DataGenerator</strong>: Generates DataLoaders for ranking and multi-task models</li><li><strong>MatchDataGenerator</strong>: Generates DataLoaders for matching models</li><li><strong>SequenceDataGenerator</strong>: Generates DataLoaders for HSTU/HLLM sequence tasks</li><li><strong>ParquetIterableDataset</strong>: Streams Parquet files batch by batch</li></ul><p>See <a href="/torch-rechub/core/data.html">Data Pipeline</a> for details.</p><h3 id="training-and-evaluation" tabindex="-1">Training and Evaluation <a class="header-anchor" href="#training-and-evaluation" aria-label="Permalink to “Training and Evaluation”">​</a></h3><p>The training-and-evaluation component trains different types of recommendation models, including:</p><ul><li><strong>CTRTrainer</strong>: Trains ranking models</li><li><strong>MatchTrainer</strong>: Trains matching models</li><li><strong>MTLTrainer</strong>: Trains multi-task models</li><li><strong>SeqTrainer</strong>: Trains HSTU/HLLM sequence-generation models</li></ul><p>RQ-VAE and TIGER use dedicated data-processing and training workflows. See <a href="/torch-rechub/models/generative.html">Generative Models</a> and the corresponding reproduction guides.</p><p>See <a href="/torch-rechub/core/evaluation.html">Training and Evaluation</a> for details.</p>',22)])])}const h=a(o,[["render",i]]);export{u as __pageData,h as default};
